'* { box-sizing: border-box; font-family: ''Segoe UI'', Roboto, Arial, sans-serif; }
body, div { color: #FFFAF3; }
.vazio { color: #ECDCC7; padding: 12px; font-size: 13px; }
.next { display: flex; gap: 12px; overflow-x: auto; padding: 2px; }
.hero { flex: 1 1 260px; min-width: 260px; background: #1E3D58; border-left: 5px solid #7AE582; border-radius: 10px; padding: 10px 14px; }
.top { display: flex; justify-content: space-between; gap: 8px; align-items: center; }
.eb { font-size: 10.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: #FFCFA6; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.st { font-size: 11.5px; font-weight: 700; white-space: nowrap; }
.st i, .dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 6px; }
.nm { font-size: 18px; font-weight: 800; margin: 4px 0; }
.meta { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 13px; font-weight: 700; }
.meta b, .obs b, .kv b { display: block; font-size: 10px; text-transform: uppercase; letter-spacing: .06em; color: #FFCFA6; font-weight: 700; }
.obs { font-size: 12.5px; margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.obs b { display: inline; margin-right: 6px; }
.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 14px; }
.card { background: #152739; border: 1px solid #2B4561; border-top: 3px solid #7AE582; border-radius: 10px; padding: 14px 16px; }
.card h3 { margin: 0 0 4px; font-size: 16px; color: #FFFAF3; }
.when { font-size: 13px; color: #ECDCC7; margin-bottom: 10px; }
.when strong { color: #FFFAF3; }
.badge { float: right; font-size: 12px; font-weight: 700; padding: 3px 9px; border-radius: 999px; background: #1C3147; color: #FFFAF3; }
.kv { display: grid; grid-template-columns: max-content 1fr; gap: 6px 14px; font-size: 13px; }
.kv b { display: inline; font-size: 12px; text-transform: none; letter-spacing: 0; color: #B8A68F; }
.past { opacity: .62; }
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid #2B4561; vertical-align: top; }
thead th { font-size: 11px; text-transform: uppercase; letter-spacing: .05em; color: #B8A68F; background: #1C3147; }
tr.grp td { font-weight: 800; padding-top: 14px; border-bottom: 2px solid #2B4561; color: #FFFAF3; }
tr.grp span { font-weight: 500; color: #B8A68F; margin-left: 8px; }
td.nm2 { font-weight: 700; }
td.dt { white-space: nowrap; }
.leg div { display: flex; align-items: center; font-size: 13px; padding: 4px 2px; }
.leg span { margin-left: auto; color: #B8A68F; }
.hd h1 { margin: 0; font-size: 22px; font-weight: 800; color: #FFFAF3; }
.hd p { margin: 2px 0 0; font-size: 13px; color: #ECDCC7; }
'
